import 'package:etecsa_supervision/domain/entities/movi.dart';
import 'package:etecsa_supervision/infraestructure/model/moviedb/movie_dbmovie.dart';

class MovieMapper {
  static Movie moviedbToEntity(MovieMovieDB movidb) => Movie(
    adult: movidb.adult,
    backdropPath: movidb.backdropPath != '' ? 'https://image.tmdb.org/t/p/w500${movidb.backdropPath}': 'data:image/png;base64,',
    genreIds: movidb.genreIds.map((e)=> e.toString()).toList(),
    id: movidb.id,
    originalLanguage: movidb.originalLanguage,
    originalTitle: movidb.originalTitle,
    overview: movidb.overview,
    popularity: movidb.popularity,
    posterPath: movidb.posterPath != '' ? 'https://image.tmdb.org/t/p/w500${movidb.posterPath}': 'data:image/png;base64,',
    releaseDate: movidb.releaseDate,
    title: movidb.title,
    video: movidb.video,
    voteAverage: movidb.voteAverage,
    voteCount: movidb.voteCount,
  );
}
